function scheduleShareUrl(){if(restoringShare)return;clearTimeout(shareTimer);shareTimer=setTimeout(()=>history.replaceState(null,'',`#${shareParams()}`),500);}
const sharedPanel=panel;
panel=(image)=>{sharedPanel(image);scheduleShareUrl();};
function restoreShareUrl(){const params=new URLSearchParams(location.hash.slice(1));if(!params.size)return;restoringShare=true;const rover=params.get('rover');if(rovers[rover]){s.rover=rover;$('#roverSelect').value=rover;sols(rovers[rover].latest)}for(const [key]of ROVER_FILTERS[s.rover]||[]){const value=params.get(key);if(value==='0'||value==='1')s.roverFilters[s.rover][key]=value==='1'}syncPerseveranceUi();const sol=params.get('sol');if(sol&&$('#solSelect').querySelector(`option[value="${sol}"]`))$('#solSelect').value=sol;for(const [key,field]of [['yaw','yaw'],['pitch','pitch'],['fov','fov']]){const value=Number(params.get(key));if(Number.isFinite(value))s[field]=value*D}const theme=params.get('theme');if(theme==='dark'||theme==='light'){document.documentElement.dataset.theme=theme;$('#themeToggle').textContent=theme==='dark'?'☾':'☼'}pendingSharedSelection=selectionFromCoordinates(Number(params.get('selectionAzimuth')),Number(params.get('selectionElevation')),Number(params.get('selectionRadius')));if(pendingSharedSelection)showSelectionWait();pendingSharedImage=pendingSharedSelection?null:params.get('image');$('#loadButton').click();let attempts=0;const reveal=setInterval(()=>{const image=s.images.find(item=>item.imageid===pendingSharedImage);if(image){panel(image);pendingSharedImage=null;clearInterval(reveal);restoringShare=false;scheduleShareUrl()}else if(!pendingSharedImage||++attempts>250){pendingSharedImage=null;clearInterval(reveal);restoringShare=false;scheduleShareUrl()}},100);}
window.addEventListener('hashchange',restoreShareUrl);
restoreShareUrl();

// Keep the three Sol controls as one state.  The number field accepts only
// positive integers; it quietly snaps to the nearest selectable Sol when a
// value falls outside the mission range.
const populateSols=sols;
document.querySelectorAll('[data-i18n-tooltip]').forEach(element=>{element.dataset.tooltip=t[element.dataset.i18nTooltip]||element.dataset.tooltip;});
sols=(max,selected=max)=>{populateSols(max,selected);syncSolControls();};
function availableSols(){return [...$('#solSelect').options].map(option=>+option.value).sort((a,b)=>a-b)}
function nearestSol(value){const values=availableSols();return values.reduce((best,sol)=>Math.abs(sol-value)<Math.abs(best-value)?sol:best,values[0]||0)}
function flashSolCorrection(){const control=$('.sol-direct-control');control.classList.remove('corrected');void control.offsetWidth;control.classList.add('corrected');}
function syncSolControls(){const select=$('#solSelect'),input=$('#solInput');if(!select||!input)return;const value=+select.value,values=availableSols(),min=values[0]||0,max=values.at(-1)||0;input.value=value;input.setAttribute('aria-valuemin',min);input.setAttribute('aria-valuemax',max);input.setAttribute('aria-valuenow',value);$('#previousSolButton').disabled=value<=min;$('#nextSolButton').disabled=value>=max;}
function selectSol(value,{loadPanorama=true,corrected=false}={}){const next=nearestSol(value),select=$('#solSelect');if(!Number.isFinite(next))return;const changed=+select.value!==next;if(changed&&(s.selection||s.selectionDraft))clearSelection();select.value=next;syncSolControls();if(corrected)flashSolCorrection();if(changed&&loadPanorama)$('#loadButton').click();else if(!changed)scheduleShareUrl();}
function stepSol(direction){const values=availableSols(),current=+$('#solSelect').value,index=values.indexOf(current);selectSol(values[Math.max(0,Math.min(values.length-1,index+direction))]);}
function commitSolInput(){const input=$('#solInput'),raw=input.value;if(!/^\d+$/.test(raw)||+raw<1){syncSolControls();flashSolCorrection();return;}const requested=+raw,actual=nearestSol(requested);selectSol(actual,{corrected:actual!==requested});}
$('#solSelect').addEventListener('change',()=>{if(s.selection||s.selectionDraft)clearSelection();syncSolControls();scheduleShareUrl();});
$('#solInput').addEventListener('input',(event)=>{const clean=event.target.value.replace(/\D/g,'');if(clean!==event.target.value){event.target.value=clean;flashSolCorrection();}});
$('#solInput').addEventListener('change',commitSolInput);
$('#solInput').addEventListener('keydown',(event)=>{if(event.key==='Enter'){event.preventDefault();commitSolInput();event.target.blur();}});
$('#previousSolButton').addEventListener('click',()=>stepSol(-1));
$('#nextSolButton').addEventListener('click',()=>stepSol(1));
$('#roverSelect').onchange=async(event)=>{if(s.selection||s.selectionDraft)clearSelection();s.rover=event.target.value;s.yaw=0;s.pitch=0;s.pointer=null;const rover=rovers[s.rover];await discoverLatest(rover);sols(rover.latest);scheduleShareUrl();};
syncSolControls();

// Export is intentionally a JSON work manifest: it retains the original API
// records and the parsed CAHV vectors beside the downloaded image files.
const sleep=milliseconds=>new Promise(resolve=>setTimeout(resolve,milliseconds));
function downloadName(image,index){const path=new URL(url(image),location.href).pathname.split('/').pop();return path||`${String(index+1).padStart(3,'0')}-${image.imageid||'mars-image'}.jpg`;}
function saveBlob(blob,name){const href=URL.createObjectURL(blob),link=document.createElement('a');link.href=href;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(href),2000);}
function closeDownloadNotice(){$('#downloadNotice').hidden=true}
function showDownloadNotice(copied){const notice=$('#downloadNotice'),text=$('#downloadNoticeText'),close=$('#closeDownloadNotice');text.textContent=copied?(t.downloadNoticeCopied||'Metadata JSON downloaded. Image URL List Copied to Clipboard.'):(t.downloadNoticeUnavailable||'Metadata JSON downloaded. Image URL List could not be copied to Clipboard.');close.setAttribute('aria-label',t.closeNotice||'Close notification');notice.hidden=false;close.focus()}
$('#closeDownloadNotice').onclick=closeDownloadNotice;
$('#downloadNotice').addEventListener('click',event=>{if(event.target===$('#downloadNotice'))closeDownloadNotice()});
window.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#downloadNotice').hidden)closeDownloadNotice()});
async function saveImage(image,index){const response=await fetch(url(image),{cache:'force-cache',mode:'cors'});if(!response.ok)throw Error(`HTTP ${response.status}`);saveBlob(await response.blob(),downloadName(image,index));}
function exportManifest(images=activeImages()){const strip=({element,...image})=>image;return {format:'mars-rover-360-export/v1',exportedAt:new Date().toISOString(),rover:s.rover,sol:+$('#solSelect').value,view:{yawDegrees:s.yaw/D,pitchDegrees:s.pitch/D,fovDegrees:s.fov/D},images:images.map((image,index)=>({...strip(image),downloadFile:downloadName(image,index),cameraGeometry:image.model?{type:image.model.type,C:image.model.C,A:image.model.A,H:image.model.H,V:image.model.V,subframe:bounds(image,image.element)}:null}))};}
async function tryZipDownload(images){debug('ZIP export started', `${images.length} images`);if(!window.JSZip){debug('ZIP export failed','No same-origin image byte access or ZIP runtime is available.');return false;}try{const zip=new window.JSZip;for(let index=0;index<images.length;index++){const response=await fetch(url(images[index]),{cache:'force-cache',mode:'cors'});if(!response.ok)throw Error(`HTTP ${response.status}`);zip.file(downloadName(images[index],index),await response.blob());}saveBlob(await zip.generateAsync({type:'blob'}),`mars-rover-360-${s.rover}-sol-${$('#solSelect').value}.zip`);debug('ZIP export succeeded', `${images.length} images`);return true;}catch(error){debug('ZIP export failed', error.name||'unknown error');return false;}}
async function copyImageUrls(images){const text=images.map(url).join('\n');try{await navigator.clipboard.writeText(text);return true;}catch{const area=document.createElement('textarea');area.value=text;area.style.cssText='position:fixed;opacity:0';document.body.append(area);area.select();const copied=document.execCommand('copy');area.remove();return copied;}}
async function downloadAll(){const button=$('#downloadAllButton'),images=[...activeImages()];if(!images.length||button.disabled)return;button.disabled=true;try{saveBlob(new Blob([JSON.stringify(exportManifest(images),null,2)],{type:'application/json'}),`mars-rover-360-${s.rover}-sol-${$('#solSelect').value}-manifest.json`);if(!await tryZipDownload(images)){await sleep(DOWNLOAD_DELAY_MS);for(let index=0;index<images.length;index++){try{await saveImage(images[index],index)}catch(error){debug('Image export blocked', `${downloadName(images[index],index)}: ${error.name||'unknown error'}`);break}if(index<images.length-1)await sleep(DOWNLOAD_DELAY_MS);}}showDownloadNotice(await copyImageUrls(images))}finally{button.disabled=false}}
$('#downloadAllButton').addEventListener('click',downloadAll);

function selectionCap(selection=s.selectionDraft||s.selection){const cap=selection;if(!cap)return null;const cosine=Math.max(-1,Math.min(1,dot(cap.center,cap.edge||cap.center)));return {...cap,radius:Math.acos(cosine)};}
function capRay(center,radius,angle){const reference=Math.abs(center[2])<.9?[0,0,1]:[1,0,0],u=norm(cross(reference,center)),v=norm(cross(center,u)),co=Math.cos(radius),si=Math.sin(radius);return norm(center.map((value,index)=>value*co+(u[index]*Math.cos(angle)+v[index]*Math.sin(angle))*si));}
function drawSelectionOverlay(){const cap=selectionCap();if(!cap)return;cx.save();cx.strokeStyle='rgba(82,238,255,.96)';cx.lineWidth=4;cx.shadowColor='rgba(0,225,255,.72)';cx.shadowBlur=12;cx.beginPath();let open=false;for(let index=0;index<=96;index++){const projected=project(capRay(cap.center,cap.radius,index/96*Math.PI*2));if(projected){if(open)cx.lineTo(projected.x,projected.y);else{cx.moveTo(projected.x,projected.y);open=true;}}else open=false;}cx.stroke();const center=project(cap.center);if(center){cx.fillStyle='#53e7ff';cx.beginPath();cx.arc(center.x,center.y,4,0,Math.PI*2);cx.fill();}cx.restore();}
function selectedImageIds(cap){return s.images.filter(image=>{const b=bounds(image,image.element),center=ray(image,b.l+b.w/2,b.top+b.h/2);return center&&Math.acos(Math.max(-1,Math.min(1,dot(cap.center,center))))<=cap.radius;}).map(image=>image.imageid)}
function gallerySection(title,images,note=''){const section=document.createElement('section'),heading=document.createElement('h2');section.className='gallery-section';heading.textContent=title;section.append(heading);if(note){const detail=document.createElement('p');detail.className='gallery-note';detail.textContent=note;section.append(detail)}for(const image of images){const element=document.createElement('img');element.src=image.pdsDecodedDataUrl||url(image);element.alt=image.imageid;element.loading='lazy';section.append(element)}return section}
function renderGallery(){const gallery=$('#image-gallery'),selected=s.selection?.ids?.length?activeImages():[],sections=[];/* Selection always comes first.  The Perseverance FHaz archive remains
below it even while the panorama uses Navcam-only placement. */if(selected.length)sections.push(gallerySection(t.selectedImageGallery||'Selected images',selected));if(s.rover==='perseverance')sections.push(gallerySection('Fisheye camera products',s.fisheyeImages,'Excluded from the panorama layer; retained here for this Sol.'));gallery.replaceChildren(...sections);gallery.hidden=!sections.length;}
function clearGallery(){renderGallery();}
function showSelectionPanel(){const count=s.selection?.ids.length||0;$('#imagePanel').classList.add('selectionMode');$('#imagePanel .eyebrow').textContent=t.selectionPanelTitle||'IMAGE SELECTION';$('#imageTitle').textContent=(t.imagesSelected||'{count} IMAGES SELECTED').replace('{count}',count);$('#closePanel').hidden=true;$('#downloadAllButton').textContent=t.downloadSelected||'Download selected';$('#imagePanel').hidden=false;}
function clearSelection(){s.selection=null;s.selectionDraft=null;$('#imagePanel').classList.remove('selectionMode');$('#imagePanel .eyebrow').textContent=t.imagePanelEyebrow||'IMAGE INFO PANEL';$('#closePanel').hidden=false;panel(null);renderGallery();render();}
const normalPanel=panel;
panel=(image)=>{if(!image&&s.selection){$('#imagePanel').hidden=true;return;}$('#imagePanel').classList.remove('selectionMode');$('#imagePanel .eyebrow').textContent=t.imagePanelEyebrow||'IMAGE INFO PANEL';$('#closePanel').hidden=false;normalPanel(image);};
function beginSelection(event){const current=point(event),rayAtPointer=unproject(current.x,current.y);s.selectionDraft={center:rayAtPointer,edge:rayAtPointer,ids:[]};wrap.setPointerCapture?.(event.pointerId);render();}
function updateSelection(event){const current=point(event);s.selectionDraft.edge=unproject(current.x,current.y);s.selectionDraft.ids=selectedImageIds(selectionCap());render();}
function finishSelection(event){const cap=selectionCap(),ids=s.selectionDraft?.ids||selectedImageIds(cap);s.selectionDraft=null;wrap.releasePointerCapture?.(event.pointerId);if(!ids.length){clearSelection();return;}s.selection={center:cap.center,edge:cap.edge,ids};renderGallery();showSelectionPanel();render();}
function restorePendingSelection(){if(!pendingSharedSelection||!s.images.length)return;const shared=pendingSharedSelection;pendingSharedSelection=null;const cosine=Math.max(-1,Math.min(1,dot(shared.center,shared.edge))),cap={...shared,radius:Math.acos(cosine)},ids=selectedImageIds(cap);dismissSelectionWait();if(!ids.length)return;s.selection={...shared,ids};renderGallery();showSelectionPanel();render();}
const navigatePointerDown=wrap.onpointerdown,navigatePointerMove=wrap.onpointermove,navigatePointerUp=wrap.onpointerup;
wrap.onpointerdown=(event)=>{if(event.shiftKey&&event.button===0){event.preventDefault();beginSelection(event);return;}navigatePointerDown(event);};
wrap.onpointermove=(event)=>{if(s.selectionDraft){event.preventDefault();updateSelection(event);return;}navigatePointerMove(event);};
wrap.onpointerup=(event)=>{if(s.selectionDraft){event.preventDefault();finishSelection(event);return;}navigatePointerUp(event);};
wrap.addEventListener('dblclick',(event)=>{if(event.shiftKey){event.preventDefault();event.stopImmediatePropagation();}},{capture:true});
window.addEventListener('keydown',(event)=>{if(event.key==='Escape'&&(s.selection||s.selectionDraft)){event.preventDefault();clearSelection();}});

function syncPerseveranceUi(){const controls=$('#roverImageFilters'),groups=ROVER_FILTERS[s.rover]||[];if(!controls)return;controls.hidden=!groups.length;controls.replaceChildren();const legend=document.createElement('legend');legend.textContent=`${rovers[s.rover].name} image layers`;controls.append(legend);for(const [key,label]of groups){const control=document.createElement('label'),input=document.createElement('input'),text=document.createElement('span');input.type='checkbox';input.checked=s.roverFilters[s.rover][key]!==false;input.dataset.roverFilter=key;text.textContent=label;control.append(input,text);controls.append(control)}}
$('#roverImageFilters').addEventListener('change',event=>{const input=event.target;if(!input.matches('[data-rover-filter]'))return;s.roverFilters[s.rover][input.dataset.roverFilter]=input.checked;render();scheduleShareUrl();});
$('#roverSelect').addEventListener('change',()=>{syncPerseveranceUi();renderGallery();});
syncPerseveranceUi();

// Crossview slideshow -------------------------------------------------------
// A browse record is allowed to enter this feature only after it has passed
// the same camera-model gate as the panorama.  Location vectors are optional:
// when they are absent, the UI calls the result a directional grouping rather
// than claiming a confirmed common ground point.
const crossviewState={reference:null,focus:null,groups:[],collecting:false,run:0,status:'',statusError:false,phase:'idle',secondTarget:null,settings:{window:5,angle:17,overlap:20,minDistance:1,maxDistance:1000,units:'metric'}};
const crossviewSolCache=new Map;
const crossviewText=(key,values={})=>String(t[key]||key).replace(/\{(\w+)\}/g,(_,name)=>values[name]??'');
const crossviewTextNode=value=>document.createTextNode(value);

function crossviewSetStatus(message,error=false){crossviewState.status=message;crossviewState.statusError=error;const status=$('#crossviewStatus');if(status){status.textContent=message;status.classList.toggle('error',error)}}
function crossviewDimensions(image){const dimension=vec(image.extended?.dimension)||[],subframe=vec(image.subframe_rect||image.extended?.subframeRect)||[];return{naturalWidth:dimension[0]||subframe[2]||1024,naturalHeight:dimension[1]||subframe[3]||1024}}
function crossviewRayAtPixel(image,pixel){if(!image?.model)return null;const size=crossviewDimensions(image),box=bounds(image,size),x=Math.max(0,Math.min(size.naturalWidth,Number(pixel?.x))),y=Math.max(0,Math.min(size.naturalHeight,Number(pixel?.y)));if(!Number.isFinite(x)||!Number.isFinite(y))return null;return ray(image,box.l+x/size.naturalWidth*box.w,box.top+y/size.naturalHeight*box.h)}
function crossviewRay(image){const size=crossviewDimensions(image);return crossviewRayAtPixel(image,{x:size.naturalWidth/2,y:size.naturalHeight/2})}
function crossviewAngle(a,b){return Math.acos(Math.max(-1,Math.min(1,dot(a,b))))}
function crossviewFamily(image){const value=`${image.instrument||''} ${imageIdentity(image)}`.toUpperCase();if(/NAV|NLG|NLF/.test(value))return'navcam';if(/MAST/.test(value))return'mastcam';if(/HAZ/.test(value))return'hazcam';if(/SUPERCAM/.test(value))return'supercam';return String(image.instrument||'other').toLowerCase()}
function crossviewVector(value){if(Array.isArray(value)&&value.length>=3){const result=value.slice(0,3).map(Number);if(result.every(Number.isFinite))return result}const result=vec(value);return result?.length===3&&result.every(Number.isFinite)?result:null}
function crossviewPosition(image){const extended=image.extended||{},candidates=[image.roverPose?.position,image.rover_pose?.position,image.pose?.position,image.rover_position,image.roverPosition,extended.roverPosition,extended.rover_position,extended.xyz,image.xyz];for(const candidate of candidates){const position=crossviewVector(candidate);if(position)return position}return null}
function crossviewObservation(raw,rover){const image={...normalizeRoverImage(raw,rover),model:null};image.model=model(image);if(!usablePanoramaModel(image.model,rover)||isTransferThumbnail(image)||image.is_thumbnail||/(thumbnail|thumb)/i.test(image.sample_type||''))return null;image.crossviewRay=crossviewRay(image);image.crossviewPosition=crossviewPosition(image);image.crossviewFamily=crossviewFamily(image);return image.crossviewRay?image:null}
function crossviewReferenceObservation(image,rover){const pixel=image?.crossviewPixel,normalized=crossviewObservation(image,rover);if(normalized){if(pixel){normalized.crossviewPixel=pixel;normalized.crossviewRay=crossviewRayAtPixel(normalized,pixel)}return normalized.crossviewRay?normalized:null}const fallback={...image,crossviewRay:pixel?crossviewRayAtPixel(image,pixel):crossviewRay(image),crossviewPosition:crossviewPosition(image),crossviewFamily:crossviewFamily(image),crossviewPixel:pixel};return fallback.crossviewRay?fallback:null}
function crossviewImageCone(image){const axis=image.crossviewRay||crossviewRay(image),apex=image.crossviewPosition;if(!axis)return null;const size=crossviewDimensions(image),corners=[[0,0],[size.naturalWidth,0],[0,size.naturalHeight],[size.naturalWidth,size.naturalHeight]].map(([x,y])=>crossviewRayAtPixel(image,{x,y})).filter(Boolean),family=crossviewFamily(image),maximum=(family==='navcam'?40:family==='mastcam'?18:family==='supercam'?12:85)*D,halfAngle=Math.min(maximum,Math.max(0,...corners.map(corner=>crossviewAngle(axis,corner))));return{apex,axis,halfAngle}}
function crossviewTargetCone(reference){return{apex:reference.crossviewPosition,axis:reference.crossviewRay,halfAngle:crossviewState.settings.angle*D,minDistance:Math.max(.25,Number(crossviewState.settings.minDistance)||.25),maxDistance:Math.max(.5,Number(crossviewState.settings.maxDistance)||.5)}}
// The control measures how much of the *candidate image's* field contains
// the selected direction cone.  Dividing by the target cone instead would
// make a broad image score 100% even when the target occupies only a tiny
// part of it, which is precisely the weak match this control must reject.
function crossviewConeOverlap(first,second){const a=first.halfAngle,b=second.halfAngle,d=crossviewAngle(first.axis,second.axis);if(d>=a+b)return 0;const area=d<=Math.abs(a-b)?Math.PI*Math.min(a,b)**2:(()=>{const x=(a*a+d*d-b*b)/(2*d),y=Math.sqrt(Math.max(0,a*a-x*x));return a*a*Math.acos(Math.max(-1,Math.min(1,x/a)))+b*b*Math.acos(Math.max(-1,Math.min(1,(d-x)/b)))-d*y})();return Math.max(0,Math.min(1,area/(Math.PI*b*b)))}
function crossviewPairIntersection(reference,candidate){const first=reference.crossviewPosition,second=candidate.crossviewPosition;if(!first||!second)return null;const d1=reference.crossviewRay,d2=candidate.crossviewRay,r=first.map((value,index)=>value-second[index]),a=dot(d1,d2),denominator=1-a*a;if(denominator<1e-6)return null;const b=dot(d1,r),c=dot(d2,r),distance1=(a*c-b)/denominator,distance2=(c-a*b)/denominator;if(distance1<=0||distance2<=0)return null;const q1=first.map((value,index)=>value+distance1*d1[index]),q2=second.map((value,index)=>value+distance2*d2[index]),gap=Math.hypot(...q1.map((value,index)=>value-q2[index]));if(!Number.isFinite(gap))return null;return{target:q1.map((value,index)=>(value+q2[index])/2),gap,baseline:Math.hypot(...r),distance1,distance2}}
function crossviewConeIntersection(first,second){if(!first?.apex||!second?.apex)return null;const minimum=Math.max(.25,Number(first.minDistance)||.25),maximum=Math.max(minimum,Number(first.maxDistance)||minimum);for(let step=0;step<=128;step++){const distance=minimum===maximum?minimum:minimum*(maximum/minimum)**(step/128),point=first.apex.map((value,index)=>value+distance*first.axis[index]),toPoint=point.map((value,index)=>value-second.apex[index]),range=Math.hypot(...toPoint);if(range<.25)continue;/* At this range the selected angular cone is a disc of radius
distance·tan(a).  Its apparent radius from the candidate rover—not the
constant full target tolerance—is what may extend into the image cone. */const targetAngularRadius=Math.asin(Math.min(1,distance*Math.tan(first.halfAngle)/range));if(crossviewAngle(norm(toPoint),second.axis)<=targetAngularRadius+(second.halfAngle||0))return{distance,range,targetAngularRadius}}return null}
function crossviewConesIntersect(first,second){if(!first?.axis||!second?.axis||crossviewConeOverlap(first,second)<crossviewState.settings.overlap/100)return false;if(!first.apex||!second.apex)return true;return Boolean(crossviewConeIntersection(first,second))}
function crossviewReset(image=null){crossviewState.run++;crossviewStopAll();crossviewState.reference=null;crossviewState.focus=image;crossviewState.groups=[];crossviewState.collecting=false;crossviewState.status='';crossviewState.statusError=false;crossviewState.phase='idle';crossviewState.secondTarget=null}
function crossviewTargetDirection(image,target){const position=image.crossviewPosition;if(!position||!target)return null;return norm(target.map((value,index)=>value-position[index]))}
function crossviewTargetRegion(reference,candidate,intersection){const targetingTolerance=Math.tan(1*D),radius=Math.max(intersection.gap/2,intersection.distance1*targetingTolerance,intersection.distance2*targetingTolerance);return{center:intersection.target,radius,firstDistance:intersection.distance1,secondDistance:intersection.distance2}}
function crossviewSecondTargetIsPrecise(intersection){return intersection&&intersection.gap<=Math.max(2,intersection.baseline*.05)&&Math.max(intersection.distance1,intersection.distance2)<=intersection.baseline*2}
function crossviewImageIntersectsRegion(image,region){const cone=crossviewImageCone(image),direction=crossviewTargetDirection(image,region?.center);if(!cone||!direction)return false;const range=crossviewDistance(image.crossviewPosition,region.center);if(range<=region.radius)return crossviewAngle(cone.axis,direction)<=cone.halfAngle;return crossviewAngle(cone.axis,direction)<=cone.halfAngle+Math.asin(Math.min(1,region.radius/range))}
function crossviewBuildRefinedGroup(reference,secondTarget,candidates){const target=secondTarget.target,region=secondTarget.region,matched=candidates.filter(candidate=>crossviewImageIntersectsRegion(candidate,region));const slides=crossviewOrderSlides(crossviewUnique([reference,secondTarget.image,...crossviewUniqueViews(matched)]),reference,target);return slides.length>1?{id:'refined-target',kind:'refined',referenceImageId:reference.imageid,target,targetRegion:region,meanGap:secondTarget.intersection.gap,slides,active:slides.map(()=>true),index:0,timer:null}:null}
function crossviewDistance(a,b){return Math.hypot(...a.map((value,index)=>value-b[index]))}
function crossviewRotateToReference(slides,reference){const index=slides.findIndex(slide=>slide.imageid===reference.imageid);return index>0?[...slides.slice(index),...slides.slice(0,index)]:slides}
function crossviewOrderSlides(slides,reference,target){const decorated=slides.map(slide=>{const position=slide.crossviewPosition;let bearing=0;if(target&&position){bearing=Math.atan2(position[1]-target[1],position[0]-target[0])}else{const direction=slide.crossviewRay;bearing=Math.atan2(direction[1],direction[0])}return{slide,bearing}}).sort((a,b)=>a.bearing-b.bearing).map(item=>item.slide);return crossviewRotateToReference(decorated,reference)}
