function terrain3dTick(now=performance.now()){const state=terrain3dState;if(state.mode==='terrain'&&state.renderer){const delta=Math.min(.05,(now-state.controls.last)/1000),controls=state.controls,forward=[Math.cos(controls.yaw),Math.sin(controls.yaw)],right=[-forward[1],forward[0]];controls.last=now;const moving=['w','a','s','d','e','c'].some(key=>state.keys.has(key));if(moving&&controls.locked)controls.locked=false;const move=(key,vector)=>state.keys.has(key)&&(state.camera.position.x+=vector[0]*controls.speed*delta,state.camera.position.y+=vector[1]*controls.speed*delta);if(!controls.locked){move('w',forward);move('s',forward.map(value=>-value));move('a',right.map(value=>-value));move('d',right);if(state.keys.has('e'))state.camera.position.z+=controls.speed*delta;if(state.keys.has('c'))state.camera.position.z-=controls.speed*delta;const target=new state.three.THREE.Vector3(state.camera.position.x+Math.cos(controls.pitch)*Math.cos(controls.yaw),state.camera.position.y+Math.cos(controls.pitch)*Math.sin(controls.yaw),state.camera.position.z+Math.sin(controls.pitch));state.camera.lookAt(target)}else{const p=controls.pitch,r=controls.radius;state.camera.position.set(controls.target.x+r*Math.cos(p)*Math.cos(controls.yaw),controls.target.y+r*Math.cos(p)*Math.sin(controls.yaw),controls.target.z+r*Math.sin(p));state.camera.up.set(0,0,1);state.camera.lookAt(controls.target)}state.renderer.render(state.scene,state.camera)}state.animation=requestAnimationFrame(terrain3dTick)}
async function terrain3dSynthesize(){const run=++terrain3dState.run,rover=rovers[s.rover],center=Number($('#solSelect').value),windowSize=Math.max(1,Math.floor(Number($('#terrainSolWindow').value)||1)),range=crossviewSolRange(center,windowSize,rover.latest),sols=[];for(let sol=range.start;sol<=range.end;sol++)sols.push(sol);terrain3dStatus(`Collecting Sol ${range.start}–${range.end}…`);const records=await crossviewLoadSols(rover,sols,run);if(run!==terrain3dState.run)return;const inputs=records.filter(image=>crossviewFamily(image)==='navcam').filter(image=>terrain3dPairKey(image)).slice(0,28);terrain3dState.inputs=inputs;$('#terrain3dInputCount').textContent=`${inputs.length} inputs`;terrain3dState.origin=terrain3dOrigin(inputs.find(image=>Number(image.sol)===center)||inputs[0]||s.panoramaImages[0]);terrain3dCreateSurface([]);await terrain3dProjectInputs(inputs);await terrain3dLoadRover();terrain3dResize();terrain3dStatus(`Flat fallback + ${inputs.length} image projections`);let points=[];for(const pair of terrain3dStereoPairs(inputs)){if(run!==terrain3dState.run)return;const found=await terrain3dStereoPoints(pair);if(found.length){points.push(...found);terrain3dCreateSurface(points);await terrain3dProjectInputs(inputs);terrain3dStatus(`Mesh refining: ${points.length} stereo points · ${inputs.length} projections`)}}if(run===terrain3dState.run)terrain3dStatus(points.length?`Mesh complete: ${points.length} stereo points`:'No valid stereo triangulation; flat projection fallback active')}
async function terrain3dSetMode(mode){if(mode===terrain3dState.mode)return;terrain3dState.mode=mode;const terrain=mode==='terrain',host=$('#terrain3dView');host.hidden=!terrain;wrap.classList.toggle('is-terrain-mode',terrain);$('#panoramaModeButton').classList.toggle('is-active',!terrain);$('#terrainModeButton').classList.toggle('is-active',terrain);$('#panoramaModeButton').setAttribute('aria-pressed',String(!terrain));$('#terrainModeButton').setAttribute('aria-pressed',String(terrain));if(!terrain)return;try{terrain3dStatus('Starting WebGL terrain…');await terrain3dInitialize();terrain3dResize();terrain3dSynthesize()}catch(error){terrain3dStatus('3D view unavailable');debug('Terrain view failed',error.message||'unknown error')}}
$('#panoramaModeButton').onclick=()=>terrain3dSetMode('panorama');$('#terrainModeButton').onclick=()=>terrain3dSetMode('terrain');let terrainWindowTimer=null;$('#terrainSolWindow').oninput=()=>{const input=$('#terrainSolWindow'),value=Math.max(1,Math.floor(Number(input.value)||1));terrain3dState.halfWindow=value;clearTimeout(terrainWindowTimer);terrainWindowTimer=setTimeout(()=>{input.value=String(value);if(terrain3dState.mode==='terrain')terrain3dSynthesize()},180)};
window.addEventListener('keydown',event=>{if(terrain3dState.mode!=='terrain'||event.target.matches('input,select,textarea'))return;const key=event.key.toLowerCase();if(key==='r'&&!event.repeat){event.preventDefault();const controls=terrain3dState.controls;controls.locked=!controls.locked;if(controls.locked){controls.target.set(0,0,0);const offset=terrain3dState.camera.position.clone().sub(controls.target);controls.radius=Math.max(2,offset.length());controls.yaw=Math.atan2(offset.y,offset.x);controls.pitch=Math.asin(Math.max(-.96,Math.min(.96,offset.z/controls.radius)));terrain3dStatus('Rover-centered orbit camera')}else terrain3dStatus('Free drone camera');return}if(!['w','a','s','d','e','c'].includes(key))return;event.preventDefault();terrain3dState.keys.add(key)});window.addEventListener('keyup',event=>terrain3dState.keys.delete(event.key.toLowerCase()));
